      if (!new Prisma.Decimal(breakdown.remuneration).plus(breakdown.employer).eq(original.amount) || !original.amount.eq(breakdown.total)) throw new Error("Memória dos componentes diverge do total provisionado.");
      if (!component && new Prisma.Decimal(breakdown.employer).gt(0)) throw new Error("Provisão com encargos exige plano financeiro com componente explícito do empenho.");
